pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint128 amount, uint64 futureDelta) public {
        // Restrict sender to a valid, non-zero Ethereum address
        vm.assume(sender != address(0) && sender != address(this));
        // Ensure the future unlock time is at least 1 second in the future
        vm.assume(futureDelta > 0);
        // Bound the amount to be non-zero and less than max
        vm.assume(amount > 0);

        uint256 depositAmount = uint256(amount);
        uint256 unlockTime = block.timestamp + uint256(futureDelta);

        // Deal ether to sender and make the Put call
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Put{value: depositAmount}(unlockTime);

        // After Put, immediately attempt to Collect the full amount
        // Since unlockTime > block.timestamp, this should revert (Collect fails)
        bool collectReverted = false;
        vm.prank(sender);
        try c.Collect(depositAmount) {
            // If it doesn't revert, collectReverted stays false
        } catch {
            collectReverted = true;
        }

        // The correct contract C must revert (collectReverted == true).
        // The buggy version sets unlockTime to block.timestamp, so Collect would succeed (collectReverted == false).
        assertTrue(collectReverted);
    }
}

