pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 first, uint256 second, uint256 unlock1, uint256 unlock2, address depositor) public {
        // bound to admissible huge values to keep domain wide
        first = bound(first, 0.01 ether, 100 ether);
        second = bound(second, 0.01 ether, 100 ether);
        unlock1 = bound(unlock1, 0, type(uint128).max);
        unlock2 = bound(unlock2, 0, type(uint128).max);
        vm.assume(depositor != address(0));

        vm.deal(depositor, first + second);

        // deposit first
        vm.prank(depositor);
        c.Put{value: first}(unlock1);

        // deposit second
        vm.prank(depositor);
        c.Put{value: second}(unlock2);

        // get accumulated balance
        (, uint256 balance) = c.Acc(depositor);

        // general rule: total balance = sum of all msg.value deposits
        assertTrue(balance == first + second);
    }
}

