pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount1, uint256 amount2) public {
        vm.assume(caller != address(0));
        vm.assume(amount1 >= 1 ether && amount1 < 1000 ether);
        vm.assume(amount2 >= 1 ether && amount2 < 1000 ether);
        vm.assume(amount1 + amount2 > amount1); // no overflow

        // First Put
        vm.deal(caller, amount1);
        vm.prank(caller);
        c.Put{value: amount1}(block.timestamp + 1000);

        // Second Put from same caller
        vm.deal(caller, amount2);
        vm.prank(caller);
        c.Put{value: amount2}(block.timestamp + 1000);

        // Sum of all deposits
        uint256 totalDeposited = amount1 + amount2;

        // Sum of all recorded values in Log History plus contract ETH balance
        // Log.History records every Put; msg.value for the two calls are amount1 and amount2
        (,,,, uint val1) = c.LogFile().History(0);
        (,,,, uint val2) = c.LogFile().History(1);
        uint256 totalRecorded = val1 + val2 + address(c).balance;

        // The contract's own Eth balance + total recorded msg.value must equal totalDeposited*2 (since each Put deposits and records once, but the contract holds the ether; if balance overwritten, mismatch appears)
        assertTrue(totalRecorded == totalDeposited * 2);
    }
}

