pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount, uint256 extraAmount) public {
        amount = bound(amount, 1 ether, type(uint256).max / 2);
        extraAmount = bound(extraAmount, 1 ether, type(uint128).max);
        unlockTime = bound(unlockTime, 0, block.timestamp + 365 days);

        // Deploy attacker contract that will re-enter via fallback
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount + extraAmount);
        vm.prank(address(attacker));
        attacker.attack{value: amount}(unlockTime);

        // After attack, the total recorded balances in Acc should not exceed the contract's ether balance
        // because every balance increase corresponds to an actual ether deposit.
        // However, the mutant allows re-entrant Put calls to inflate balance without adding real ether.
        assertTrue(address(c).balance >= c.Acc(address(attacker)));
    }
}

