pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // Restrict to admissible domain: amount > 0 and at least MinSum, unlockTime >= 0
        uint256 minSum = c.MinSum();
        vm.assume(amount >= minSum && amount < type(uint128).max);
        vm.assume(unlockTime > 0 && unlockTime < type(uint128).max);

        // Set up a clean sender address
        address sender = address(0xb0b);
        vm.deal(sender, amount * 2);

        // Put funds with a fixed exploit-friendly unlockTime
        vm.prank(sender);
        c.Put{value: amount}(unlockTime);

        // Warp exactly to unlockTime, where the bug manifests
        vm.warp(unlockTime);

        // Now attempt Collect; reference must revert, buggy succeeds
        bool success;
        vm.prank(sender);
        try c.Collect(amount) {
            success = true;
        } catch {
            success = false;
        }

        // Reference rule: at equality, Collect must revert (success == false)
        // Buggy version succeeds (success == true) -> rule violated.
        assertTrue(!success);
    }
}

