pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amt, uint8 delta) public {
        // amt: amount used in Put and Collect
        // delta: small future offset for unlockTime (1..255 seconds from now)
        vm.assume(amt >= 1 ether && amt <= 100 ether);
        vm.assume(delta >= 1);
        uint unlockTime = block.timestamp + delta;
        address sender = address(0x100);
        vm.deal(sender, amt + 1 ether);
        // Provide the contract with enough balance for the low-level call to succeed
        vm.deal(address(c), 1 ether);
        vm.startPrank(sender);
        c.Put{value: amt}(unlockTime);
        vm.stopPrank();
        // Warp to exactly unlockTime (where reference requires strict >, mutant allows >=)
        vm.warp(unlockTime);
        uint balanceBefore = c.Acc(sender).balance;
