pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 existing) public {
        // The fuzzer picks an existing tracked balance and an amount to deposit.
        // We must keep the domain wide; the only assumption is that the sum
        // (existing + amount) does not overflow in math to avoid revert in
        // the reference. The buggy version wraps on overflow, so we exclude
        // only the case where the reference would also revert, leaving the
        // overflow zone reachable for the bug.
        vm.assume(existing <= type(uint256).max - amount);

        // Set up an arbitrary caller.
        address caller = address(0x1000);
        vm.deal(caller, amount);

        // Pre-populate the caller's tracked balance by sending existing Ether
        // through the reference logic. We use the deployed reference contract
        // for this setup; the bug is only in Put.
        vm.prank(caller);
        c.Put{value: existing}(block.timestamp);

        // Record the balance before the fuzzed Put.
        (, uint256 balanceBefore) = c.Acc(caller);

        // Perform the fuzzed Put.
        vm.prank(caller);
        c.Put{value: amount}(block.timestamp);

        // Read the balance after the Put.
        (, uint256 balanceAfter) = c.Acc(caller);

        // General rule: after depositing `amount`, the recorded balance must
        // increase exactly by `amount`. The reference addition (sub_uint256
        // after add_uint256 which asserts no overflow) satisfies this.
        // The buggy mutant uses wrapping addition, so for large sums the
        // balanceAfter will be less than balanceBefore + amount.
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

