pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, uint256 putAmount, uint256 unlockTime) public {
        // bound unlockTime to avoid any edge-case timestamp issues, but keep it wide
        unlockTime = bound(unlockTime, 1, type(uint64).max);
        // bound initialBalance to a reasonable range that still allows overflow detection
        initialBalance = bound(initialBalance, 0, type(uint128).max);
        // putAmount must be at least 1 wei to have a meaningful Put call
        vm.assume(putAmount > 0);

        // Set up an actor with initial balance by pre-depositing if initialBalance > 0
        address actor = address(0x1234);
        if (initialBalance > 0) {
            vm.deal(actor, initialBalance);
            vm.prank(actor);
            c.Put{value: initialBalance}(1);
        }

        // Prepare for the Put call that should be compared
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Compute the expected balance using the reference's exact add_uint256 logic
        uint256 expectedBalance;
        unchecked {
            expectedBalance = initialBalance + putAmount;
        }
        // The reference's add_uint256 asserts(c >= a), so it would revert on overflow;
        // The buggy mutant allows overflow so the stored balance would be different.
        // We observe the actual stored balance via the public getter Acc(actor).balance
        (uint actualUnlockTime, uint actualBalance) = c.Acc(actor);

        // The property: the recorded balance must equal the sum of all msg.value sent by that caller.
        // For the reference, this always holds (or reverts). For the buggy mutant, when overflow occurs,
        // actualBalance will be less than expectedBalance, violating the property.
        assertTrue(actualBalance == expectedBalance);
    }
}

